export type ProjectStatus = "on-track" | "at-risk" | "blocked" | "complete";
export type DashboardScope = "all" | "mine" | "attention";
export interface DashboardMember {
  id: string;
  name: string;
  role: string;
  src?: string;
}
export interface DashboardProject {
  id: string;
  code: string;
  title: string;
  client: string;
  summary: string;
  ownerId: string;
  status: ProjectStatus;
  completed: number;
  total: number;
  due: string;
  href?: string;
}
export interface DashboardTask {
  id: string;
  title: string;
  projectId: string;
  assigneeId?: string;
  due: string;
  priority: "high" | "normal";
  done: boolean;
}
export interface DashboardActivity {
  id: string;
  actorId?: string;
  projectId?: string;
  action: string;
  at: string;
}
export interface DashboardHistoryPoint {
  date: string;
  projects: readonly { projectId: string; completed: number; total: number }[];
}
export interface DashboardSnapshot {
  id: string;
  organization: string;
  asOf: string;
  currentMemberId: string;
  members: readonly DashboardMember[];
  projects: readonly DashboardProject[];
  tasks: readonly DashboardTask[];
  activity: readonly DashboardActivity[];
  history?: readonly DashboardHistoryPoint[];
}
export interface Dashboard01Props {
  snapshot?: DashboardSnapshot;
  title?: string;
  description?: string;
  locale?: string;
  loading?: boolean;
  error?: string;
  retry?: () => void;
  refresh?: () => void;
  createProject?: () => void;
  openProject?: (project: DashboardProject) => void | Promise<void>;
  updateTask?: (id: string, done: boolean) => void | Promise<void>;
}
export const projectStatuses: readonly ProjectStatus[] = [
  "on-track",
  "at-risk",
  "blocked",
  "complete",
];
export const projectStatusLabels: Record<ProjectStatus, string> = {
  "on-track": "On track",
  "at-risk": "At risk",
  blocked: "Blocked",
  complete: "Complete",
};
export const projectStatusTone = (status: ProjectStatus) =>
  status === "on-track"
    ? "success"
    : status === "at-risk"
      ? "warning"
      : status === "blocked"
        ? "danger"
        : "brand";
export const dashboardScopes: readonly {
  value: DashboardScope;
  label: string;
}[] = [
  { value: "all", label: "Whole workspace" },
  { value: "mine", label: "My work" },
  { value: "attention", label: "Needs attention" },
];
export function dashboardDay(value: string) {
  return new Date(value).toISOString().slice(0, 10);
}
export function dashboardDate(
  value: string,
  locale = "en-GB",
  withTime = false,
) {
  return new Intl.DateTimeFormat(locale, {
    day: "numeric",
    month: "short",
    year: "numeric",
    ...(withTime ? { hour: "2-digit", minute: "2-digit" } : {}),
    timeZone: "UTC",
  }).format(new Date(value));
}
export const projectPercent = (project: DashboardProject) =>
  Math.round((project.completed / project.total) * 100);
export const projectNeedsAttention = (
  project: DashboardProject,
  asOf: string,
) =>
  project.status === "at-risk" ||
  project.status === "blocked" ||
  (project.status !== "complete" && project.due < dashboardDay(asOf));
const realDay = (value: string) =>
  typeof value === "string" &&
  /^\d{4}-\d{2}-\d{2}$/.test(value) &&
  Number.isFinite(Date.parse(value)) &&
  dashboardDay(value) === value;
const realInstant = (value: string) =>
  typeof value === "string" &&
  /T.*(?:Z|[+-]\d{2}:\d{2})$/.test(value) &&
  realDay(value.slice(0, 10)) &&
  Number.isFinite(Date.parse(value));
export function validateDashboard(input: DashboardSnapshot): DashboardSnapshot {
  const id = (value: string) =>
    typeof value === "string" && /^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(value);
  const memberIds = new Set<string>(),
    projectIds = new Set<string>(),
    taskIds = new Set<string>(),
    activityIds = new Set<string>();
  if (!id(input.id) || !input.organization?.trim() || !realInstant(input.asOf))
    throw Error(
      "Dashboard needs a workspace ID, name and explicit snapshot timestamp.",
    );
  const members = input.members.map((member) => {
    if (!id(member.id) || memberIds.has(member.id) || !member.name?.trim())
      throw Error("Members require unique IDs and names.");
    memberIds.add(member.id);
    return { ...member };
  });
  if (!memberIds.has(input.currentMemberId))
    throw Error("The current member must be present in the workspace.");
  let total = 0,
    completed = 0;
  const projects = input.projects.map((project) => {
    if (
      !id(project.id) ||
      projectIds.has(project.id) ||
      !project.title?.trim() ||
      !project.code?.trim() ||
      !memberIds.has(project.ownerId) ||
      !projectStatuses.includes(project.status) ||
      !realDay(project.due) ||
      !Number.isSafeInteger(project.total) ||
      project.total < 1 ||
      !Number.isSafeInteger(project.completed) ||
      project.completed < 0 ||
      project.completed > project.total ||
      (project.status === "complete" && project.completed !== project.total)
    )
      throw Error(
        "Projects need unique IDs, valid ownership, dates and delivery counts.",
      );
    if (project.href) {
      const href = project.href.trim(),
        url = new URL(href, "https://paraxe.invalid/");
      if (!href || href.startsWith("//") || url.protocol !== "https:")
        throw Error("Project destinations must be relative or HTTPS.");
    }
    projectIds.add(project.id);
    total += project.total;
    completed += project.completed;
    return { ...project };
  });
  if (!Number.isSafeInteger(total) || !Number.isSafeInteger(completed))
    throw Error("Project delivery totals are too large.");
  const tasks = input.tasks.map((task) => {
    if (
      !id(task.id) ||
      taskIds.has(task.id) ||
      !task.title?.trim() ||
      !projectIds.has(task.projectId) ||
      (task.assigneeId && !memberIds.has(task.assigneeId)) ||
      !realDay(task.due) ||
      !["high", "normal"].includes(task.priority) ||
      typeof task.done !== "boolean"
    )
      throw Error(
        "Priorities need unique IDs, valid project/owner references and due dates.",
      );
    taskIds.add(task.id);
    return { ...task };
  });
  const activity = input.activity.map((event) => {
    if (
      !id(event.id) ||
      activityIds.has(event.id) ||
      !event.action?.trim() ||
      (event.actorId && !memberIds.has(event.actorId)) ||
      (event.projectId && !projectIds.has(event.projectId)) ||
      !realInstant(event.at) ||
      Date.parse(event.at) > Date.parse(input.asOf)
    )
      throw Error(
        "Activity must reference known records and valid snapshot times.",
      );
    activityIds.add(event.id);
    return { ...event };
  });
  const historyDates = new Set<string>();
  const history = input.history?.map((point) => {
    if (
      !realDay(point.date) ||
      point.date > dashboardDay(input.asOf) ||
      historyDates.has(point.date)
    )
      throw Error("History needs unique dates no later than the snapshot.");
    historyDates.add(point.date);
    const ids = new Set<string>();
    const records = point.projects.map((record) => {
      if (
        !projectIds.has(record.projectId) ||
        ids.has(record.projectId) ||
        !Number.isSafeInteger(record.total) ||
        record.total < 1 ||
        !Number.isSafeInteger(record.completed) ||
        record.completed < 0 ||
        record.completed > record.total
      )
        throw Error("History needs valid project delivery counts.");
      ids.add(record.projectId);
      return { ...record };
    });
    if (ids.size !== projectIds.size)
      throw Error(
        "Each history date must cover the snapshot projects for comparable scopes.",
      );
    if (
      !Number.isSafeInteger(records.reduce((sum, item) => sum + item.total, 0))
    )
      throw Error("History totals are too large.");
    return { ...point, projects: records };
  });
  return { ...input, members, projects, tasks, activity, history };
}
export function dashboardView(
  snapshot: DashboardSnapshot,
  scope: DashboardScope,
  query = "",
  status: ProjectStatus | "all" = "all",
  showCompleted = false,
) {
  const mine = new Set(
    snapshot.tasks
      .filter((task) => task.assigneeId === snapshot.currentMemberId)
      .map((task) => task.projectId),
  );
  const projects = snapshot.projects.filter(
    (project) =>
      scope === "all" ||
      (scope === "mine"
        ? project.ownerId === snapshot.currentMemberId || mine.has(project.id)
        : projectNeedsAttention(project, snapshot.asOf)),
  );
  const projectIds = new Set(projects.map((project) => project.id));
  const member = (id: string) =>
    snapshot.members.find((person) => person.id === id)!;
  const total = projects.reduce((sum, project) => sum + project.total, 0),
    completed = projects.reduce((sum, project) => sum + project.completed, 0);
  const day = dashboardDay(snapshot.asOf),
    week = dashboardDay(
      new Date(Date.parse(`${day}T00:00:00Z`) + 7 * 86400000).toISOString(),
    );
  const terms = query
    .trim()
    .toLocaleLowerCase("en-GB")
    .split(/\s+/)
    .filter(Boolean);
  const rows = projects
    .filter(
      (project) =>
        (status === "all" || project.status === status) &&
        terms.every((term) =>
          `${project.code} ${project.title} ${project.client} ${member(project.ownerId).name}`
            .toLocaleLowerCase("en-GB")
            .includes(term),
        ),
    )
    .map((project) => ({
      ...project,
      ownerName: member(project.ownerId).name,
      progressPercent: projectPercent(project),
      statusLabel: projectStatusLabels[project.status],
    }));
  const scopedTasks = snapshot.tasks.filter(
    (task) =>
      projectIds.has(task.projectId) &&
      (scope !== "mine" || task.assigneeId === snapshot.currentMemberId),
  );
  const trend = (snapshot.history ?? [])
    .map((point) => {
      const scoped = point.projects.filter((item) =>
          projectIds.has(item.projectId),
        ),
        total = scoped.reduce((sum, item) => sum + item.total, 0),
        completed = scoped.reduce((sum, item) => sum + item.completed, 0);
      return {
        date: point.date,
        total,
        completed,
        percentage: total ? Math.round((completed / total) * 100) : 0,
      };
    })
    .sort((a, b) => a.date.localeCompare(b.date));
  return {
    trend,
    trendTicks: trend
      .map((point, index) => ({ point, index }))
      .filter(
        ({ index }) =>
          index === 0 ||
          index === Math.floor((trend.length - 1) / 2) ||
          index === trend.length - 1,
      ),
    projects,
    rows,
    total,
    completed,
    percentage: total ? Math.round((completed / total) * 100) : 0,
    active: projects.filter((project) => project.status !== "complete").length,
    attention: projects.filter((project) =>
      projectNeedsAttention(project, snapshot.asOf),
    ).length,
    dueSoon: projects.filter(
      (project) =>
        project.status !== "complete" &&
        project.due >= day &&
        project.due <= week,
    ).length,
    distribution: projectStatuses.map((status) => ({
      status,
      label: projectStatusLabels[status],
      count: projects.filter((project) => project.status === status).length,
    })),
    priorities: scopedTasks
      .filter((task) => showCompleted || !task.done)
      .sort(
        (a, b) =>
          Number(a.done) - Number(b.done) ||
          a.due.localeCompare(b.due) ||
          Number(b.priority === "high") - Number(a.priority === "high") ||
          a.id.localeCompare(b.id),
      ),
    pendingTasks: scopedTasks.filter((task) => !task.done).length,
    deadlines: projects
      .filter((project) => project.status !== "complete")
      .sort((a, b) => a.due.localeCompare(b.due) || a.id.localeCompare(b.id))
      .slice(0, 3),
    ownership: snapshot.members
      .filter((person) =>
        projects.some((project) => project.ownerId === person.id),
      )
      .map((person) => ({
        ...person,
        active: projects.filter(
          (project) =>
            project.ownerId === person.id && project.status !== "complete",
        ).length,
      })),
    activity: snapshot.activity
      .filter((event) =>
        event.projectId ? projectIds.has(event.projectId) : scope === "all",
      )
      .sort(
        (a, b) =>
          Date.parse(b.at) - Date.parse(a.at) || a.id.localeCompare(b.id),
      )
      .slice(0, 5),
  };
}
