.dashboard01 {
  --dashboard01-gap: var(--grid-gap);
  --dashboard01-axis-width: calc(var(--typography-micro-size) * 5);
  max-width: var(--container-max-width);
  margin-inline: auto;
  padding: var(--container-padding-lg);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.dashboard01 *,
.dashboard01 *::before,
.dashboard01 *::after {
  box-sizing: border-box;
}
:where(.dashboard01) :where(h1, h2, h3, p, ul, ol) {
  margin: 0;
}
.dashboard01-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--grid-gap);
  padding-block: var(--space-3) var(--card-padding);
}
.dashboard01-eyebrow {
  font-family: var(--font-family-mono);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
  font-weight: var(--font-weight-medium);
  text-transform: uppercase;
  color: var(--text-muted);
}
.dashboard01-header h1 {
  font-size: var(--font-size-3xl);
  line-height: var(--typography-heading-lineheight);
  letter-spacing: var(--typography-heading-letterspacing);
  margin-block: var(--space-3) var(--space-2);
}
.dashboard01-header .text {
  color: var(--text-secondary);
  font-size: var(--font-size-sm);
}
.dashboard01-header-actions {
  display: flex;
  gap: var(--space-2);
  flex-wrap: wrap;
  flex-shrink: 0;
}
.dashboard01-context {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  flex-wrap: wrap;
  padding-block: var(--card-padding-sm);
  border-top: var(--border-width-thin) solid var(--border-default);
  font-size: var(--font-size-xs);
  color: var(--text-muted);
}
.dashboard01-context label {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  color: var(--text-secondary);
}
.dashboard01-context .select {
  min-width: var(--space-48);
}
.dashboard01-context time {
  color: var(--text-secondary);
  margin-inline-start: var(--space-2);
  font-variant-numeric: tabular-nums;
}
.dashboard01-overview-grid {
  display: flex;
  align-items: stretch;
  gap: var(--dashboard01-gap);
  margin-block-end: var(--dashboard01-gap);
}
.dashboard01-overview,
.dashboard01-panel {
  border: var(--border-width-thin) solid var(--card-border);
  background: var(--card-background);
  border-radius: var(--card-radius);
  box-shadow: var(--card-shadow);
  min-width: 0;
}
.dashboard01-overview {
  flex: 2.15;
  padding: var(--card-padding);
  display: flex;
  flex-direction: column;
}
.dashboard01-overview-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  margin-block-end: var(--card-padding);
}
.dashboard01-pulse {
  display: flex;
  flex-wrap: wrap;
  gap: var(--card-padding);
  align-items: center;
  flex: 1;
}
.dashboard01-completion {
  flex: 0 0 auto;
  max-width: 100%;
  min-width: 0;
  align-self: start;
  padding-block-start: var(--space-4);
}
.dashboard01 .stat {
  border: 0;
  box-shadow: none;
  border-radius: var(--radius-none);
  background: transparent;
  padding: 0;
}
.dashboard01-completion .stat {
  gap: var(--space-2);
}
.dashboard01-completion .stat-value {
  font-family: var(--font-family-display);
  font-size: var(--typography-hero-size);
  line-height: var(--line-height-none);
  font-weight: var(--typography-heading-weight);
  letter-spacing: var(--letter-spacing-tighter);
  color: var(--brand-primary);
  white-space: nowrap;
}
.dashboard01-completion > p {
  font-size: var(--font-size-xs);
  color: var(--text-muted);
  line-height: var(--line-height-relaxed);
  margin-block: var(--space-3);
}
.dashboard01-completion > .progress {
  max-width: var(--space-32);
}
.dashboard01-completion .progress-label {
  position: absolute;
  width: var(--border-width-thin);
  height: var(--border-width-thin);
  overflow: hidden;
  clip-path: inset(50%);
}
.dashboard01-trend {
  flex: 1 1 calc(var(--space-48) + var(--space-24));
  min-width: min(100%, calc(var(--space-48) + var(--space-24)));
}
.dashboard01-trend-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-2);
  margin-block-end: var(--space-4);
}
.dashboard01-trend-heading h3 {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
}
.dashboard01-trend-heading > span {
  color: var(--text-muted);
  font-size: var(--typography-micro-size);
}
.dashboard01-trend-plot {
  display: flex;
  gap: var(--space-2);
}
.dashboard01-trend-scale {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
  flex: 0 0 var(--dashboard01-axis-width);
  width: var(--dashboard01-axis-width);
  text-align: end;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.dashboard01-trend-lines {
  flex: 1;
  min-width: 0;
  background: repeating-linear-gradient(
    to bottom,
    var(--chart-grid) 0,
    var(--chart-grid) var(--border-width-thin),
    transparent var(--border-width-thin),
    transparent 50%
  );
  border-bottom: var(--border-width-thin) solid var(--chart-grid);
}
.dashboard01-trend .sparkline {
  width: 100%;
  height: auto;
  display: block;
  overflow: visible;
}
.dashboard01-trend-dates {
  position: relative;
  height: var(--space-4);
  margin-block-start: var(--space-2);
  margin-inline-start: calc(var(--dashboard01-axis-width) + var(--space-2));
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.dashboard01-trend-dates > span {
  position: absolute;
  transform: translateX(-50%);
  white-space: nowrap;
}
.dashboard01-trend-dates > span:first-child {
  transform: none;
}
.dashboard01-trend-dates > span:last-child {
  transform: translateX(-100%);
}
.dashboard01-trend-data {
  margin-block-start: var(--space-3);
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.dashboard01-trend-data summary {
  cursor: pointer;
  text-align: end;
  text-decoration: underline;
  text-underline-offset: var(--space-1);
}
.dashboard01-trend-data table {
  width: 100%;
  margin-block-start: var(--space-3);
  border-collapse: collapse;
  font-size: var(--font-size-xs);
  color: var(--text-secondary);
}
.dashboard01-trend-data th,
.dashboard01-trend-data td {
  padding: var(--space-2);
  border-bottom: var(--border-width-thin) solid var(--border-subtle);
  text-align: start;
}
.dashboard01-trend-empty {
  padding-block: var(--card-padding-lg);
  font-size: var(--font-size-sm);
  color: var(--text-muted);
  line-height: var(--line-height-relaxed);
}
.dashboard01-metrics {
  display: flex;
  border-top: var(--border-width-thin) solid var(--border-default);
  padding-block-start: var(--card-padding-sm);
  margin-block-start: var(--card-padding);
}
.dashboard01-metrics > div {
  flex: 1;
  min-width: 0;
  padding-inline: var(--card-padding-sm);
  border-inline-start: var(--border-width-thin) solid var(--border-default);
}
.dashboard01-metrics > div:first-child {
  padding-inline-start: 0;
  border: 0;
}
.dashboard01-metrics > div:last-child {
  padding-inline-end: 0;
}
.dashboard01-metrics .stat {
  flex-direction: column-reverse;
  gap: var(--space-2);
}
.dashboard01-metrics .stat-value {
  font-size: var(--font-size-2xl);
  line-height: var(--line-height-tight);
}
.dashboard01-metrics .stat-label {
  font-size: var(--font-size-xs);
  color: var(--text-primary);
}
.dashboard01-metrics p {
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
  margin-block-start: var(--space-1);
  line-height: var(--line-height-relaxed);
}
.dashboard01-panel {
  padding: var(--card-padding);
}
.dashboard01-panel h2 {
  font-size: var(--font-size-lg);
  line-height: var(--typography-heading-lineheight);
  letter-spacing: var(--typography-heading-letterspacing);
  margin-block-start: var(--space-2);
}
.dashboard01-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  margin-block-end: var(--card-padding);
}
.dashboard01-priorities {
  flex: 1;
  display: flex;
  flex-direction: column;
  border-block-start: var(--border-width-strong) solid var(--brand-primary);
}
.dashboard01-tasks,
.dashboard01-deadlines ol,
.dashboard01-activity ol,
.dashboard01-people ul {
  padding: 0;
  list-style: none;
}
.dashboard01-tasks > li {
  padding-block: var(--card-padding-sm);
  border-bottom: var(--border-width-thin) solid var(--border-subtle);
}
.dashboard01-tasks > li:first-child {
  padding-block-start: 0;
}
.dashboard01-tasks .checkbox {
  align-items: start;
  min-height: 0;
}
.dashboard01-tasks .checkbox-control {
  margin-block-start: var(--space-1);
}
.dashboard01-tasks .checkbox-label {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.dashboard01-tasks p {
  margin-inline-start: calc(var(--control-decoration-size) + var(--space-2));
  margin-block-start: var(--space-2);
  font-size: var(--typography-micro-size);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.dashboard01-task--done .checkbox-label {
  text-decoration: line-through;
  color: var(--text-muted);
}
.dashboard01-task-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-2);
  padding-block-start: var(--card-padding-sm);
  margin-block-start: auto;
  font-size: var(--font-size-xs);
}
.dashboard01-projects {
  overflow: hidden;
  padding: 0;
}
.dashboard01-projects > .dashboard01-panel-head {
  padding: var(--card-padding) var(--card-padding) 0;
}
.dashboard01-health {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  padding: var(--card-padding-sm) var(--card-padding);
  border-block: var(--border-width-thin) solid var(--border-subtle);
  background: var(--surface-raised);
}
.dashboard01-health h3 {
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
  white-space: nowrap;
}
.dashboard01-health-summary {
  display: none;
}
.dashboard01-health-bar {
  height: var(--space-2);
  display: flex;
  gap: var(--border-width-thin);
  overflow: hidden;
  border-radius: var(--radius-full);
  background: var(--surface-raised);
  flex: 1;
  max-width: var(--space-48);
}
.dashboard01-health--on-track {
  background: var(--color-success);
}
.dashboard01-health--at-risk {
  background: var(--color-warning);
}
.dashboard01-health--blocked {
  background: var(--color-danger);
}
.dashboard01-health--complete {
  background: var(--brand-primary);
}
.dashboard01-legend {
  padding: 0;
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
  font-size: var(--font-size-xs);
  color: var(--text-secondary);
  margin-inline-start: auto;
}
.dashboard01-legend li {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.dashboard01-dot {
  display: inline-block;
  width: var(--space-2);
  height: var(--space-2);
  border-radius: var(--radius-full);
}
.dashboard01-filters {
  display: flex;
  align-items: end;
  gap: var(--grid-gap-sm);
  padding: var(--card-padding-sm) var(--card-padding);
}
.dashboard01-filters label {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: var(--space-2);
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
}
.dashboard01-filters label:first-child {
  flex: 2;
}
.dashboard01-filters label:last-child {
  max-width: calc(var(--space-48) + var(--space-16));
}
.dashboard01 .table {
  max-width: 100%;
  overflow-x: auto;
  border: 0;
  border-radius: var(--radius-none);
  background: transparent;
}
.dashboard01 .table table {
  min-width: var(--content-width-wide);
}
.dashboard01 .table-caption {
  text-align: start;
  padding: 0 var(--card-padding) var(--space-3);
  font-size: var(--font-size-xs);
  color: var(--text-muted);
}
.dashboard01 .table th:first-child,
.dashboard01 .table td:first-child {
  padding-inline-start: var(--card-padding);
}
.dashboard01 .table th:last-child,
.dashboard01 .table td:last-child {
  padding-inline-end: var(--card-padding);
}
.dashboard01 .table td {
  padding-block: var(--card-padding-sm);
  vertical-align: middle;
}
.dashboard01 .table th {
  white-space: nowrap;
  font-size: var(--typography-micro-size);
}
.dashboard01 .table th:first-child {
  width: 32%;
}
.dashboard01-project-name {
  display: flex;
  align-items: start;
  flex-direction: column-reverse;
  gap: var(--space-2);
}
.dashboard01-project-name > span {
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.dashboard01 a {
  color: var(--text-primary);
  text-underline-offset: var(--space-1);
}
.dashboard01-project-name .btn,
.dashboard01-deadlines .btn {
  padding: 0;
  min-height: 0;
  white-space: normal;
  text-align: start;
  justify-content: start;
  text-decoration: none;
  font-size: var(--font-size-sm);
  letter-spacing: var(--letter-spacing-normal);
  font-weight: var(--font-weight-medium);
}
.dashboard01-project-name .btn:hover,
.dashboard01-deadlines .btn:hover {
  text-decoration: underline;
}
.dashboard01-owner {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}
.dashboard01-owner > span {
  font-size: var(--font-size-xs);
  white-space: nowrap;
}
.dashboard01-progress {
  min-width: var(--space-24);
  max-width: var(--space-40);
}
.dashboard01-progress .progress-label {
  font-size: var(--typography-micro-size);
}
.dashboard01-progress > span {
  display: block;
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
  margin-block-start: var(--space-1);
}
.dashboard01-due {
  font-size: var(--font-size-xs);
  white-space: nowrap;
}
.dashboard01-due > span {
  display: block;
  color: var(--color-danger);
  font-size: var(--typography-micro-size);
  margin-block-start: var(--space-1);
}
.dashboard01-table-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--card-padding-sm) var(--card-padding);
  border-top: var(--border-width-thin) solid var(--border-subtle);
}
.dashboard01-table-foot .text {
  font-size: var(--font-size-xs);
  color: var(--text-muted);
}
.dashboard01-deadlines {
  display: flex;
  gap: var(--card-padding);
  margin-block-start: var(--dashboard01-gap);
  align-items: center;
  background: var(--surface-raised);
  box-shadow: none;
}
.dashboard01-deadlines > .dashboard01-eyebrow {
  display: none;
}
.dashboard01-deadlines h2 {
  flex: 0 0 16%;
  margin: 0;
  font-size: var(--font-size-base);
}
.dashboard01-deadlines ol {
  display: flex;
  flex: 1;
  min-width: 0;
}
.dashboard01-deadlines li {
  flex: 1;
  min-width: 0;
  padding-inline: var(--card-padding);
  border-inline-start: var(--border-width-thin) solid var(--border-default);
}
.dashboard01-deadlines li:last-child {
  padding-inline-end: 0;
}
.dashboard01-deadlines li > div {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex-wrap: wrap;
  margin-block-end: var(--space-2);
}
.dashboard01-deadlines time,
.dashboard01-deadlines li > p {
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.dashboard01-deadlines li > p {
  margin-block-start: var(--space-1);
}
.dashboard01-support {
  display: flex;
  gap: var(--dashboard01-gap);
  margin-block-start: var(--dashboard01-gap);
  align-items: stretch;
}
.dashboard01-activity {
  flex: 2.15;
}
.dashboard01-people {
  flex: 1;
}
.dashboard01-activity li {
  display: flex;
  align-items: start;
  gap: var(--space-3);
  padding-block: var(--card-padding-sm);
  border-block-start: var(--border-width-thin) solid var(--border-subtle);
}
.dashboard01-activity li:last-child {
  padding-block-end: 0;
}
.dashboard01-activity li p:first-child {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.dashboard01-activity li p + p {
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
  margin-block-start: var(--space-1);
}
.dashboard01-people ul {
  margin-block-start: var(--card-padding);
}
.dashboard01-people li {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding-block: var(--card-padding-sm);
  border-block-start: var(--border-width-thin) solid var(--border-subtle);
}
.dashboard01-people li > div {
  flex: 1;
}
.dashboard01-people strong {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
}
.dashboard01-people p,
.dashboard01-people li > span {
  font-size: var(--typography-micro-size);
  color: var(--text-muted);
}
.dashboard01-people p {
  margin-block-start: var(--space-1);
}
.dashboard01-feedback {
  padding: var(--card-padding-sm);
  background: var(--surface-raised);
  border-inline-start: var(--border-width-strong) solid var(--brand-primary);
  margin-block-end: var(--dashboard01-gap);
  font-size: var(--font-size-sm);
}
.dashboard01-feedback[role="alert"] {
  border-color: var(--color-danger);
}
.dashboard01-state {
  display: flex;
  align-items: start;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--card-padding-lg);
  margin-block-start: var(--dashboard01-gap);
  border: var(--border-width-thin) solid var(--card-border);
  background: var(--card-background);
  border-radius: var(--card-radius);
}
@media (max-width: 1000px) {
  .dashboard01-overview-grid {
    flex-direction: column;
  }
  .dashboard01-priorities {
    flex: auto;
  }
  .dashboard01-pulse {
    gap: var(--card-padding-lg);
  }
  .dashboard01-health {
    flex-wrap: wrap;
  }
  .dashboard01-legend {
    margin-inline-start: 0;
  }
  .dashboard01-health-bar {
    max-width: none;
  }
  .dashboard01-support {
    flex-direction: column;
  }
  .dashboard01-deadlines {
    flex-direction: column;
    align-items: stretch;
  }
  .dashboard01-deadlines li:first-child {
    border: 0;
    padding-inline-start: 0;
  }
}
@media (max-width: 600px) {
  .dashboard01 {
    padding: var(--container-padding);
  }
  .dashboard01-header {
    align-items: start;
    flex-direction: column;
  }
  .dashboard01-context {
    align-items: start;
    flex-direction: column;
  }
  .dashboard01-context time {
    margin: 0;
    display: block;
    margin-block-start: var(--space-1);
  }
  .dashboard01-pulse {
    flex-direction: column;
    align-items: stretch;
    gap: var(--card-padding);
  }
  .dashboard01-completion {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--space-4);
    padding: 0;
  }
  .dashboard01-completion .stat-value {
    font-size: var(--font-size-5xl);
  }
  .dashboard01-completion > .progress {
    max-width: none;
    flex-basis: 100%;
  }
  .dashboard01-trend-heading {
    flex-direction: column;
  }
  .dashboard01-metrics {
    gap: var(--space-3);
    flex-wrap: wrap;
  }
  .dashboard01-metrics > div {
    flex-basis: 100%;
    border: 0;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-3);
  }
  .dashboard01-metrics .stat {
    flex-direction: row;
    align-items: center;
    gap: var(--space-3);
  }
  .dashboard01-metrics p {
    max-width: 50%;
    text-align: end;
  }
  .dashboard01-filters {
    flex-direction: column;
    align-items: stretch;
  }
  .dashboard01-filters label:last-child {
    max-width: none;
  }
  .dashboard01-legend {
    gap: var(--space-3);
  }
  .dashboard01-health-bar {
    flex-basis: 100%;
    order: 3;
  }
  .dashboard01-deadlines ol {
    flex-direction: column;
    gap: var(--card-padding-sm);
  }
  .dashboard01-deadlines li {
    border-inline: 0;
    border-top: var(--border-width-thin) solid var(--border-default);
    padding: var(--card-padding-sm) 0 0;
  }
  .dashboard01-deadlines li:first-child {
    padding: 0;
  }
  .dashboard01-table-foot {
    flex-direction: column;
    align-items: start;
  }
  .dashboard01-panel-head {
    align-items: start;
  }
}
